<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useRoute, useRouter } from 'vue-router'
import { archiveVersion, createAuthorization, getAuditLogs, getAuthorizations, getVersionLineage, publishVersion, revokeAuthorization } from '@/api/publication'
import type { AuditLog, AuthorizationRecord, VersionLineage } from '@/types/publication'
import { formatDate, statusMeta } from '@/utils/case'

const route=useRoute(),router=useRouter(),caseId=String(route.params.caseId),mock=import.meta.env.VITE_USE_MOCK!=='false';const authorizations=ref<AuthorizationRecord[]>([]),versions=ref<VersionLineage[]>([]),logs=ref<AuditLog[]>([]),total=ref(0),page=ref(1),action=ref(''),loading=ref(false);const authorization=ref({reference:'',scope:'仅限授权教学使用',validUntil:null as string|null});const publication=ref({authorizationId:'',validUntil:null as string|null,reviewNote:'',reviewConfirmed:false});const selected=ref('')
const validAuthorizations=computed(()=>authorizations.value.filter(item=>!item.revokedAt&&Boolean(item.validUntil)&&new Date(item.validUntil as string).getTime()>Date.now()))
const errorText=(error:unknown,fallback:string)=>error instanceof Error?error.message:fallback
async function timeline(){const value=await getAuditLogs(caseId,action.value,(page.value-1)*20);logs.value=value.items;total.value=value.total}
async function load(){if(mock)return;loading.value=true;try{[authorizations.value,versions.value]=await Promise.all([getAuthorizations(caseId),getVersionLineage(caseId)]);await timeline()}catch(error){ElMessage.error(errorText(error,'发布数据加载失败'))}finally{loading.value=false}}
async function add(){if(!authorization.value.reference.trim()){ElMessage.warning('请输入授权材料编号');return}try{await createAuthorization(caseId,authorization.value);authorization.value={reference:'',scope:'仅限授权教学使用',validUntil:null};await load();ElMessage.success('授权记录已添加')}catch(error){ElMessage.error(errorText(error,'授权添加失败'))}}
async function revoke(id:string){try{await ElMessageBox.confirm('撤销后，关联案例将无法用于新任务和学生访问。确认撤销？','撤销授权',{type:'warning'});await revokeAuthorization(id);await load();ElMessage.success('授权已撤销')}catch(error){if(error!=='cancel')ElMessage.error(errorText(error,'授权撤销失败'))}}
async function publish(){if(!selected.value||!publication.value.authorizationId||!publication.value.reviewConfirmed||!publication.value.reviewNote.trim()||!publication.value.validUntil){ElMessage.warning('请选择 READY 版本和有效授权，并填写有效期、人工复核记录后确认发布');return}try{await ElMessageBox.confirm('确认已人工复核，并生成独立教学副本？发布后不能覆盖此版本。','发布教学版本',{type:'warning'});await publishVersion(selected.value,{...publication.value,reviewNote:publication.value.reviewNote.trim(),validUntil:publication.value.validUntil});await load();ElMessage.success('教学版本已发布')}catch(error){if(error!=='cancel')ElMessage.error(errorText(error,'发布失败'))}}
async function archive(id:string){try{await ElMessageBox.confirm('归档后版本不可再进入三维工作台。确认归档？','归档教学版本',{type:'warning',confirmButtonText:'确认归档'});await archiveVersion(id);await load();ElMessage.success('教学版本已归档')}catch(error){if(error!=='cancel')ElMessage.error(errorText(error,'归档失败'))}}
onMounted(load)
</script>
<template><main class="page" v-loading="loading"><div class="head"><div><p>管理员 / 案例发布管理</p><h1>发布、授权与审计</h1></div><el-button @click="router.push(`/admin/cases/${caseId}`)">返回案例详情</el-button></div><el-alert v-if="mock" title="发布管理需要真实后端" description="Mock 模式不伪造授权记录或教学副本。请设置 VITE_USE_MOCK=false 后以管理员身份使用。" type="warning" :closable="false" show-icon/><el-alert title="READY 版本须经过人工复核并关联有效授权后，方可发布为教学版本。" type="info" :closable="false" show-icon/><el-card><template #header>授权记录</template><el-form :disabled="mock" label-position="top"><el-form-item label="授权材料编号"><el-input v-model="authorization.reference"/></el-form-item><el-form-item label="授权范围"><el-input v-model="authorization.scope" type="textarea"/></el-form-item><el-form-item label="授权有效期"><el-date-picker v-model="authorization.validUntil" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ"/></el-form-item><el-button type="primary" @click="add">新增授权</el-button></el-form><el-table :data="authorizations"><el-table-column prop="reference" label="材料编号"/><el-table-column prop="scope" label="范围"/><el-table-column label="有效期"><template #default="{row}">{{formatDate(row.validUntil)}}</template></el-table-column><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.revokedAt?'info':(!row.validUntil||new Date(row.validUntil).getTime()<=Date.now()?'warning':'success')">{{row.revokedAt?'已撤销':(!row.validUntil||new Date(row.validUntil).getTime()<=Date.now()?'已过期':'有效')}}</el-tag></template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button v-if="!row.revokedAt" link type="danger" :disabled="mock" @click="revoke(row.id)">撤销</el-button></template></el-table-column></el-table><el-empty v-if="!mock&&!authorizations.length" description="暂无授权记录"/></el-card><el-card><template #header>版本谱系与教学发布</template><el-table :data="versions"><el-table-column prop="versionNumber" label="版本号" width="90"/><el-table-column prop="id" label="版本 ID" min-width="180"/><el-table-column prop="parentVersionId" label="父版本" min-width="150"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="statusMeta(row.status).type">{{statusMeta(row.status).text}}</el-tag></template></el-table-column><el-table-column label="教学有效期"><template #default="{row}">{{formatDate(row.publication?.validUntil)}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button v-if="row.status==='PUBLISHED'" link type="danger" :disabled="mock" @click="archive(row.id)">归档</el-button></template></el-table-column></el-table><el-form :disabled="mock" label-position="top" class="form"><el-form-item label="待发布 READY 版本"><el-select v-model="selected"><el-option v-for="item in versions.filter(v=>v.status==='READY')" :key="item.id" :value="item.id" :label="`v${item.versionNumber}`"/></el-select></el-form-item><el-form-item label="关联有效授权"><el-select v-model="publication.authorizationId"><el-option v-for="item in validAuthorizations" :key="item.id" :value="item.id" :label="item.reference"/></el-select></el-form-item><el-form-item label="教学版本有效期" required><el-date-picker v-model="publication.validUntil" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ"/></el-form-item><el-form-item label="人工复核记录" required><el-input v-model="publication.reviewNote" type="textarea"/></el-form-item><el-checkbox v-model="publication.reviewConfirmed">已人工复核，确认该版本可用于教学</el-checkbox><p><el-button type="primary" @click="publish">发布独立教学副本</el-button></p></el-form></el-card><el-card><template #header>审计时间线</template><div class="filter"><el-input v-model="action" placeholder="按事件筛选，例如 VERSION_PUBLISHED"/><el-button :disabled="mock" @click="page=1;load()">查询</el-button></div><el-timeline><el-timeline-item v-for="log in logs" :key="log.id" :timestamp="formatDate(log.createdAt)"><b>{{log.action}}</b> · 操作者 {{log.actorId}}<pre>{{JSON.stringify(log.detail,null,2)}}</pre></el-timeline-item></el-timeline><el-empty v-if="!mock&&!logs.length" description="暂无审计记录"/><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="prev,pager,next,total" @current-change="load"/></el-card></main></template>
<style scoped>.page{max-width:1180px;min-height:100vh;margin:auto;padding:36px 32px}.head{display:flex;align-items:center;justify-content:space-between;margin-bottom:24px}.head p{margin:0;color:#64748b;font-size:13px}h1{margin:7px 0;color:#142d4d}.el-alert,.el-card{margin-bottom:20px}.form{margin-top:22px}.form .el-select,.form .el-date-editor{width:100%}.filter{display:flex;gap:10px;margin-bottom:16px}.filter .el-input{max-width:420px}pre{padding:8px;overflow:auto;background:#f5f7fa;font-size:12px}@media(max-width:720px){.page{padding:24px 16px}.head{align-items:flex-start;gap:12px}.filter{flex-direction:column}}</style>
